import {logisticsSummary,shiftDate,localToday} from './logistics-kpis.mjs';
const e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=n=>n===null?'—':n.toFixed(1)+'%';
export function servicePanel(state,filters,asOf){const k=logisticsSummary(state,{...filters,asOf});return `<section class="card service-panel"><div class="section-head"><div><div class="eyebrow">LOGISTICS SERVICE KPIs</div><h2 style="margin-top:6px">Delivery reliability & order quality</h2><p>Order-level measures · uses the principal/warehouse filters in Director's view.</p></div><div class="field" style="margin:0"><label for="kpiAsOf">Reporting through</label><input type="date" id="kpiAsOf" value="${asOf}" max="${localToday()}" style="padding:7px;font-size:11px"></div></div><div class="service-cards"><div><div class="row"><h3>OTIF</h3><span class="badge gray">On time · in full</span></div><strong class="${k.otifPct===0?'kpi-zero':k.otifPct===null?'kpi-unknown':''}">${pct(k.otifPct)}</strong><p>${k.otifPass} passed / ${k.otifEvaluated} evaluable due orders</p><small>${k.due} orders due · ${k.otifMiss} misses · ${k.otifUnknown} missing evidence<br>OTIF evidence coverage: ${pct(k.otifCoverage)}</small></div><div><div class="row"><h3>Order accuracy rate</h3><span class="badge gray">Product · quantity · documents</span></div><strong class="${k.accuracyPct===0?'kpi-zero':k.accuracyPct===null?'kpi-unknown':''}">${pct(k.accuracyPct)}</strong><p>${k.accurate} accurate / ${k.accuracyAssessed} assessed completed orders</p><small>${k.accuracyMissing} orders awaiting evidence / assessment<br>Accuracy assessment coverage: ${pct(k.accuracyCoverage)}</small></div></div><div class="director-bottom"><span>${k.missingCommitment} orders lack an agreed delivery date. ${asOf===localToday()?'Current-day results are provisional until day end.':'Reporting uses a completed calendar-day cutoff.'} No eligible evidence = unavailable, not 100%.</span><button class="textlink" data-action="kpi:details">Definitions & order breakdown ↗</button></div></section>`;}
export function deliveryFields(s,{field,textfield}){return `${field('Actual delivery date','deliveredDate',s.delivery?.deliveredDate||localToday(),'date','Actual receipt date, not POD-upload date or planned departure.')}${s.lines.map((l,i)=>`<div class="line"></div><h3 style="margin-bottom:13px">${e(l.order)} · ${e(l.sku)}</h3>${s.lines.length>1?`<div class="formgrid">${field('Accepted units · '+l.order,'lineAccepted'+i,s.delivery?.outcomes?.find(o=>o.order===l.order)?.accepted??l.packed,'number')}${field('Returned units · '+l.order,'lineReturned'+i,s.delivery?.outcomes?.find(o=>o.order===l.order)?.returned??0,'number')}</div>`:''}<div class="field"><label for="accuracy${i}">Delivery accuracy · ${e(l.order)}</label><select id="accuracy${i}" name="accuracy${i}"><option value="not_assessed">Not assessed</option><option value="accurate" ${s.delivery?.outcomes?.find(o=>o.order===l.order&&o.sku===l.sku)?.accuracy==='accurate'?'selected':''}>Accurate: product, quantity and documents confirmed</option><option value="inaccurate" ${s.delivery?.outcomes?.find(o=>o.order===l.order&&o.sku===l.sku)?.accuracy==='inaccurate'?'selected':''}>Error found</option></select></div>${field('Accuracy evidence / explanation · '+l.order,'accuracyReference'+i,s.delivery?.outcomes?.find(o=>o.order===l.order&&o.sku===l.sku)?.accuracyReference||'','text','Required for an accurate/error assessment; leave blank if unassessed.').replace(' required','')}`).join('')}`;}
export function deliveryPayload(s,p){const base={accepted:Number(p.accepted),returned:Number(p.returned),deliveredDate:p.deliveredDate};if(s.lines.length===1)return {...base,accuracy:p.accuracy0,accuracyReference:p.accuracyReference0};const outcomes=s.lines.map((l,i)=>({order:l.order,sku:l.sku,accepted:Number(p['lineAccepted'+i]),returned:Number(p['lineReturned'+i]),accuracy:p['accuracy'+i],accuracyReference:p['accuracyReference'+i]}));return {...base,accepted:outcomes.reduce((n,o)=>n+o.accepted,0),returned:outcomes.reduce((n,o)=>n+o.returned,0),lineOutcomes:outcomes};}
export function serviceAction(action,attrs,c){const {state,filters,asOf,modal,actionForm,field,textfield,button}=c;
 if(action==='kpi:details'){const k=logisticsSummary(state,{...filters,asOf});const trips=state.shipments.filter(t=>t.delivery&&(!filters.principal||t.principal===filters.principal)&&(!filters.warehouse||t.warehouse===filters.warehouse));return modal('Logistics KPI definitions & evidence',`<div class="help"><b>OTIF:</b> due orders whose full approved quantity was accepted on/before the agreed delivery date ÷ evaluable due orders. Split shipments are combined by original order. Overdue orders without recorded completion are misses; ambiguous historical dates/allocations are disclosed as unknown.<br><b>Order accuracy:</b> accurate orders ÷ assessed completed orders. A completed order must have its approved quantity shipped and all delivery outcomes recorded by the report cutoff. Quantity discrepancy is a known error; otherwise explicit product/quantity/document assessments are required. Unassessed orders do not count as accurate.<br>Reporting through ${asOf}. An ETA is never an agreed customer commitment.</div><div class="tablewrap"><table><thead><tr><th>ORDER</th><th>AGREED DELIVERY</th><th>OTIF</th><th>ACCURACY</th><th></th></tr></thead><tbody>${k.rows.map(r=>`<tr><td>${e(r.order)}</td><td>${e(r.promised||'Not recorded')}</td><td>${e(r.otif)}</td><td>${e(r.accuracy)}</td><td>${button('Commitment','kpi:commitment','smallbtn',`data-order="${e(r.order)}"`)}</td></tr>`).join('')}</tbody></table></div><div class="line"></div><h3>Delivery evidence</h3><p class="small muted" style="margin:10px 0">Checker / Manager can add missing delivery dates and assessments. Corrections are audited; only a Manager may change an existing actual date.</p><div class="buttons">${trips.map(t=>button(t.id+' · evidence','kpi:evidence','smallbtn',`data-shipment="${t.id}"`)).join('')||'<span class="small muted">No delivery outcomes in this scope yet.</span>'}</div>`,null);}
 if(action==='kpi:commitment'){const o=state.orders.find(o=>o.id===attrs.order);return actionForm('Agreed delivery commitment · '+o.id,`${field('Agreed customer delivery date','deliveryDueDate',o.deliveryDueDate||'','date')}${field('Customer order / agreement source reference','reference',o.commitmentReference||'')}<div class="help">Planner / Manager only. An existing commitment cannot be moved after dispatch to improve OTIF. Missing historical commitments can be entered once against their original source; the entry is audited.</div>`,'recordCommitment',p=>({...p,order:o.id}));}
 if(action==='kpi:evidence'){const s=state.shipments.find(t=>t.id===attrs.shipment);return actionForm('Delivery service evidence · '+s.id,`${deliveryFields(s,{field,textfield})}${textfield('Evidence source / correction explanation','reason')}<div class="help">Delivered quantities cannot be changed here. For multi-order shipments, re-enter per-order outcomes so totals match the recorded shipment.</div>`,'serviceEvidence',p=>{const data=deliveryPayload(s,{...p,accepted:s.delivery.accepted,returned:s.delivery.returned});return {...data,shipment:s.id,reason:p.reason};});}
}
